def components(g, bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                st=[(i,j)]; comp=[]; seen[i][j]=True
                while st:
                    a,b=st.pop(); comp.append((a,b,g[a][b]))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]!=bg:
                            seen[x][y]=True; st.append((x,y))
                comps.append(comp)
    return comps

def f(inp):
