    comps.sort(key=lambda c:min(j for _,j,_ in c))
    maxc=max(j for _,j,_ in comps[0])
    out=[[bg]* (maxc+1) for _ in range(H)]
    bottoms={i: max(i for i,_,_ in c) for i,c in enumerate(comps)}
    cur=maxc+1
    for idx,c in enumerate(comps):
        base=cur-(max(j for _,j,_ in c)-min(j for _,j,_ in c))
        # target left edge: cur-1 (touch) or 0
        tg = cur-1 if idx>0 else 0
        lo=min(j for _,j,_ in c); hi=max(j for _,j,_ in c)
        sh=hi-lo
        if tg<0: tg=0
        for a,b,v in c:
            v = [1,6,3][ (v==1) ]  # placeholder
        # recolor minority cells: component majority color
        cnt=Counter(v for _,_,v in c); maj=cnt.most_common(1)[0][0]
        for a,b,v in c:
            vv = maj if v!=maj else v
            na=a-(bottoms[idx]-max(i for i,_,_ in c)); nb=b-(tg-lo)
            out[na][nb]=vv
        cur=tg+sh+1
    return out

