def solve(inp, out):
    g=inp; H,W=len(g),len(g[0]); outH,outW=len(out),len(out[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    cs=comps(g,bg)
    objs=[]
    for c in cs:
        cnt=Counter(g[r][q] for r,q in c)
        maj=cnt.most_common(1)[0][0]
        cells=[(r,q,maj) for r,q in c]
        objs.append(cells)
    def key(o): return (min(q for _,q,_ in o), min(r for r,_,_ in o))
    objs.sort(key=key)
    rel=[]
    for o in objs:
        mr=min(r for r,_,_ in o); mc=min(q for _,q,_ in o)
        rel.append([(r-mr,q-mc,v) for r,q,v in o])
    tgt={(r,q) for r in range(outH) for q in range(outW) if out[r][q]!=0}
    sols=[]
    def bt(i,used_cells):
        if i==len(rel):
            return used_cells==tgt
        res=[]
        rl=rel[i]; rs=[r for r,_,_ in rl]; qs=[q for _,q,_ in rl]
        R1,C1=max(rs),max(qs)
        for dr in range(-R1-2,R1+3):
            for dc in range(-C1-2,C1+3):
                cur=[(r+dr,q+dc,v) for r,q,v in rl]
                ps=set((r,q) for r,q,_ in cur)
                if any(not(0<=r<outH and 0<=q<outW) for r,q,_ in cur): continue
                if ps & used_cells: continue
                touch=any((r+da,q+db) in used_cells for r,q,_ in cur for da,db in ((1,0),(-1,0),(0,1),(0,-1)))
                if not touch: continue
                res.append(ps)
        for ps in res:
            if bt(i+1, used_cells | ps): return True
        return False
    return bt(1,{(r,q) for r,q,_ in rel[0]})

