                    if any(not(0<=r<outH and 0<=q<outW) for r,q in placed): continue
                    if placed & used: continue
                    touch=any((r+da,q+db) in used for r,q in pts for da,db in((1,0),(-1,0),(0,1),(0,-1)))
                    if not touch: continue
                    soln.append((i,si,dr,dc)); 
