        for a,b in base: grid[a][b]=maj
    ab,_,ac_=anchor
    ab=sorted((p[0]-min(a for a,_ in ac_), p[1]-min(b for _,b in ac_)) for p in ac_)
    anchor_maj=Counter(inp[p[0]][p[1]] for p in ac_).most_common(1)[0][0]
