    ar=min(p[0] for p in ac_); acl=min(p[1] for p in ac_)
    for r0 in range(ar): pass
    # grid coords = rel + offset(anchor top-left)
    offs=(ar,acl)
    cur={(a+offs[0],b+offs[1]) for a,b in ab}
    painted=[cur]
    paint(list(ab),anchor_maj)
    for base,maj,orig in pieces:
        # slide horizontally towards anchor: choose dc minimal such that after shift, touching and no overlap
        origset=frozenset((a+offs[0],b+offs[1]) for a,b in base)
        best=None
        for dr in range(-5,6):
