                    # prefer smallest translation distance
                    dist=abs(dr)+abs(dc)
                    if best is None or dist<best[0]: best=(dist,(dr,dc),newf)
        dr,dc,newf=best
        cur|=newf
        for a,b in newf: grid[a][b]=maj
    return grid
