        # simpler direct
        pts=[(r_,c_) for r_,c_ in occupied_colors]
        for r_,c_ in pts:
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                if (r_+da,c_+db) in occupied_set: continue
                for pr_,pc_,col in pl_colors:
                    if (pr_,pc_)==(r_+da,c_+db): res=True
        return res
    occupied_set=set(); placed=[]
    for idx,c in enumerate(P):
        pl_col=[(x-min(a for a,b in c)-min(b for a,b in c), y-min(a for a,b in c)-min(b for a,b in c), gi[x][y]) for x,y in c]
        # proper normalization done below; redo cleanly
        ar=min(x for x,y in c); ac=min(y for x,y in c)
        rel=[(x-ar,y-ac,gi[x][y]) for x,y in c]
