        for dr in range(H-rngR+1):
            for dc in range(W-rngC+1):
                pl_col=[(a+dr,b+dc,col) for a,b,col in rel]
                ps=[(a,b) for a,b,_ in pl_col]
                if not all(0<=a<H and 0<=b<W for a,b in ps): continue
                if any((a,b) in occupied_set and occ.get((a,b))!=col for a,b,col in pl_col): continue
                if any(go[a][b]!=col for a,b,col in pl_col): continue
                # touch existing occupied cells (any color)
                touch=False
                for a,b,_ in pl_col:
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        if (a+da,b+db) in occupied_set: touch=True
                if touch:
                    dm=sum(abs(a-(x)) for a,b,col in pl_col for x,y in [(None,None)])
                    cands.append((abs(dr)+abs(dc),dr,dc))
        if not cands: return ('fail',nm,idx,len(c))
        cands.sort()
        d_,dr,dc=cands[0]
        ar0,ac0=dr,dc
        placed.append((d_,rel,(dr,dc)))
        for a,b,col in rel:
            occupied_set.add((dr+a,dc+b)); occ[(dr+a,dc+b)]=col
    ov=[[0]*W for _ in range(H)]
    for _,rel,pos in placed:
        for a,b,col in rel:
            ov[pos[0]+a][pos[1]+b]=col
