def solve(inp, maxH=None, maxW=None):
    bg=Counter(x for r_ in inp for x in r_).most_common(1)[0][0]
    P=[]
    for cc in get_comps(inp,bg):
        ar=min(x for x,y in cc); ac=min(y for x,y in cc)
        P.append({'cells':cc,'ar':ar,'ac':ac,'size':len(cc)})
    P.sort(key=lambda p:-p['size'])
    anchor=P[0]
    OV_H=anchor['ar']+max(a for a,b,_ in [(xx-ar_,yy-ac_) for xx,yy in anchor['cells']])+1
    # simpler: work with relative offsets directly
    rel=[(x-anchor['ar'],y-anchor['ac'],inp[x][y]) for x,y in anchor['cells']]
    OUT=[[bg]*40 for _ in range(40)]
    occ=set()
    for a,b,c in rel:
        R,C=anchor['ar']+a, anchor['ac']+b
        OUT[R][C]=c; occ.add((R,C))
    for pi in P[1:]:
        cands=[]
        cells=[(x-pi['ar'],y-pi['ac'],inp[x][y]) for x,y in pi['cells']]
        rngR=max(a for a,b,_ in cells)+1
        rngC=max(b for _,b,_ in cells)+1
        for dr in range(-(maxH or 40)-rngR+1, (maxH or 40)+1):
            for dc in range(-(maxW or 40)-rngC+1, (maxW or 40)+1):
                ok_all=True
                for a,b,c in cells:
                    R,C=pi['ar']+a+dr, pi['ac']+b+dc
                    if not(0<=R<(maxH or 40)) or not(0<=C<(maxW or 40)): ok_all=False;break
                    if (R,C) in occ: ok_all=False;break
                    if OUT[R][C]!=c: ok_all=False;break
                if not ok_all: continue
                touch=False
                for a,b,c in cells:
                    R,C=pi['ar']+a+dr, pi['ac']+b+dc
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            if (R+da,C+db) in occ: touch=True
                if touch:
                    cands.append((abs(dr)+abs(dc),dr,dc))
        if not cands: return None
        cands.sort()
        best=cands[0]
        for a,b,c in cells:
            R,C=pi['ar']+a+best[1], pi['ac']+b+best[2]
            OUT[R][C]=c; occ.add((R,C))
    return OUT
