            if inp[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)];seen.add((i,j));cells=[]
                while st:
                    x,y=st.pop();cells.append((x,y))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            if da==db==0:continue
                            nx,ny=x+da,y+db
                            if 0<=nx<len(inp) and 0<=ny<len(inp[0]) and inp[nx][ny]!=bg and (nx,ny) not in seen:
                                seen.add((nx,ny));st.append((nx,ny))
                P.append(cells)
    P.sort(key=lambda c:min((x,y) for x,y in c))
    OUT=[[bg]*Wsum for _ in range(Hin)]
