        nc=normcells(c)
        maj=Counter(inp[x][y] for x,y in c).most_common(1)[0][0]
        Rmax=max(a for a,b in nc); Cmax=max(b for _,b in nc)
        fits=[]
        for dr in range(Hin-Rmax+1):
            for dc in range(Wsum-Cmax+1):
                ok=True
                for a,b in nc:
                    if (dr+a,dc+b) in occ: ok=False;break
                if not ok: continue
                t=any((dr+a+da,dc+b+db) in occ for a,b in nc for da in(-1,0,1) for db in(-1,0,1) if (da or db))
                # prefer touch; tie-break by smaller dr then dc
                key=(int(t), dr*1e9+dc)
                fits.append((key,dr,dc))
        fits.sort(key=lambda z:(z[0],z[2],z[3]))
