        for a,b in nc:
            OUT[dr+a][dc+b]=maj; occ.add((dr+a,dc+b))
        if dbg: print('comp',idx,'size',len(nc),'TL',min((x,y) for x,y in c),'->',(dr,dc),'touch',fits[0][0][0])
    return OUT
